"""Generated files by Linguist's rules (go-enry) and .gitattributes."""

import asyncio
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

from deepthought.generated_files import generated_files


def _write(root, files):
    for name, text in files.items():
        path = Path(root) / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)


FILES = {
    "pb/demo.pb.go": "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage pb\n",
    "main.go": "package main\n\nfunc main() {}\n",
    "demo_pb2.py": "# Generated by the protocol buffer compiler.  DO NOT EDIT!\nx = 1\n",
    "app.py": "x = 1\n",
    "web/schema.ts": "export const a = 1\n",
    "web/app.min.js": "var a=1;" * 200 + "\n",
}


class GeneratedFilesTests(unittest.TestCase):
    def test_linguist_rules_decide_from_name_and_content(self):
        with tempfile.TemporaryDirectory() as root:
            _write(root, FILES)
            self.assertEqual(
                generated_files(root, list(FILES)),
                {
                    "demo_pb2.py": "linguist",
                    "pb/demo.pb.go": "linguist",
                    "web/app.min.js": "linguist",
                },
            )
            self.assertEqual(generated_files(root, []), {})

    def test_an_unreadable_path_is_refused(self):
        with tempfile.TemporaryDirectory() as root:
            with self.assertRaises(ValueError):
                generated_files(root, ["missing.go"])

    @unittest.skipUnless(shutil.which("git"), "git is needed for attributes")
    def test_gitattributes_override_the_rules(self):
        with tempfile.TemporaryDirectory() as root:
            _write(
                root,
                {
                    **FILES,
                    ".gitattributes": "web/schema.ts linguist-generated\n"
                    "pb/demo.pb.go -linguist-generated\n",
                },
            )
            subprocess.run(["git", "init", "-q", root], check=True)
            self.assertEqual(
                generated_files(root, list(FILES)),
                {
                    "demo_pb2.py": "linguist",
                    "web/app.min.js": "linguist",
                    "web/schema.ts": "gitattributes",
                },
            )
            # A workspace below the work tree's root reads the same attributes.
            self.assertEqual(
                generated_files(Path(root) / "web", ["schema.ts", "app.min.js"]),
                {"app.min.js": "linguist", "schema.ts": "gitattributes"},
            )


class TreeSitterGeneratedFileTests(unittest.TestCase):
    def test_file_nodes_say_which_generator_rule_marked_them(self):
        from deepthought.analysis_tools import tool_registry

        with tempfile.TemporaryDirectory() as root:
            _write(
                root,
                {
                    "demo_pb2.py": FILES["demo_pb2.py"],
                    "app.py": "import demo_pb2\n\n\ndef run():\n    return demo_pb2.x\n",
                },
            )
            tool = tool_registry.get_tool("tree-sitter", root)
            output = asyncio.run(
                tool.analyze("repo", languages={"python"}, scip_indexes=())
            )
            if output.metadata.custom_metrics["analysis_status"] == "failed":
                self.skipTest("Python grammar not installed")
            files = {
                node.properties["path"]: node.properties
                for node in output.nodes
                if "File" in node.labels
            }
            self.assertEqual(files["demo_pb2.py"]["generated_by"], "linguist")
            self.assertNotIn("generated_by", files["app.py"])


if __name__ == "__main__":
    unittest.main()
